@EventBusSubscriber(modid="vandorlabs")
public final class StorageHostChecks {
 private static final BlockPos BASE=new BlockPos(7204,84,7204),COLD=new BlockPos(7296,84,7296);static NativeStorageBlock BLOCK;private static NativeStorageItem ITEM;static BlockEntityType<NativeStorageEntity> TYPE;static net.minecraft.world.inventory.MenuType<NativeStorageMenu> MENUS;private static int checks,fault;private static boolean observe;private static BlockPos capture;private static final java.util.List<ItemStack> DROPS=new java.util.ArrayList<>();
 private static String phase(){return System.getProperty("vandorlabs.transmitterPhase","");}private static boolean enabled(){return phase().startsWith("storage-host-");}private static void need(boolean yes,String why){checks++;if(!yes)throw new AssertionError("Storage host: "+why);}
 public static class Probe extends NativeStorageEntity {Probe(BlockPos pos,BlockState state){super(TYPE,pos,state);}@Override protected void published(Visual visual){if(observe)need(getItem(0).getCount()==4&&getItem(26).getCount()==7,"all27 slots installed before projection observer");}@Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider registries){super.loadAdditional(tag,registries);if(fault!=0&&!tag.contains(PLACEMENT_RECOVERY))throw new IllegalArgumentException("Injected Storage install failure");}}
 private static final class Item extends NativeStorageItem {Item(){super(BLOCK,new net.minecraft.world.item.Item.Properties());}@Override protected boolean restore(net.minecraft.world.level.Level level,BlockPos pos,BlockState state){return fault==2?false:super.restore(level,pos,state);}}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {
  @SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled())return;var id=ResourceLocation.fromNamespaceAndPath("vandorlabs","storage_host_fixture");event.register(Registries.BLOCK,h->{BLOCK=new NativeStorageBlock(BlockBehaviour.Properties.of().strength(3).requiresCorrectToolForDrops(),()->TYPE){@Override protected net.minecraft.world.inventory.MenuType<NativeStorageMenu> menuType(){return MENUS;}};h.register(id,BLOCK);});event.register(Registries.ITEM,h->{ITEM=new Item();h.register(id,ITEM);});event.register(Registries.MENU,h->{MENUS=new net.minecraft.world.inventory.MenuType<>((net.neoforged.neoforge.network.IContainerFactory<NativeStorageMenu>)(window,inventory,buffer)->new NativeStorageMenu(MENUS,window,inventory,buffer.readBlockPos()),net.minecraft.world.flag.FeatureFlags.VANILLA_SET);h.register(id,MENUS);});event.register(Registries.BLOCK_ENTITY_TYPE,h->{TYPE=BlockEntityType.Builder.<NativeStorageEntity>of(Probe::new,BLOCK).build(null);h.register(id,TYPE);});}
  @SubscribeEvent public static void capabilities(net.neoforged.neoforge.capabilities.RegisterCapabilitiesEvent event){if(enabled())event.registerBlockEntity(net.neoforged.neoforge.capabilities.Capabilities.ItemHandler.BLOCK,TYPE,(owner,side)->owner.itemHandler());}
 }
 @SubscribeEvent public static void drop(net.neoforged.neoforge.event.entity.EntityJoinLevelEvent event){if(enabled()&&capture!=null&&event.getEntity() instanceof net.minecraft.world.entity.item.ItemEntity item&&item.position().distanceToSqr(Vec3.atCenterOf(capture))<16){DROPS.add(item.getItem().copy());event.setCanceled(true);}}
 private static NativeStorageEntity at(ServerLevel world,BlockPos pos){return (NativeStorageEntity)world.getBlockEntity(pos);}
 private static NativeStorageEntity put(ServerLevel world,BlockPos pos,CompoundTag tag){world.getChunkAt(pos);world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);world.setBlock(pos,BLOCK.defaultBlockState(),18);var owner=at(world,pos);owner.loadWithComponents(tag,world.registryAccess());return owner;}
 private static net.neoforged.neoforge.common.util.FakePlayer actor(ServerLevel world,BlockPos pos){var player=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(java.util.UUID.fromString("c853bb03-a632-4ec2-bf37-10896f453269"),"StorageHost"));player.setPos(pos.getX()+.5,pos.getY(),pos.getZ()+.5);player.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);player.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);return player;}
 private static CompoundTag source(String snbt)throws Exception{return TagParser.parseTag(snbt);}
 private static JsonObject reference()throws Exception{try(var stream=new GZIPInputStream(Files.newInputStream(Path.of(System.getProperty("vandorlabs.storageReference"))));var reader=new InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)){return JsonParser.parseReader(reader).getAsJsonObject();}}
 private static void replay(ServerLevel world)throws Exception{var source=reference();for(var row:source.getAsJsonArray("comparators")){var value=row.getAsJsonObject();var owner=put(world,BASE,new CompoundTag());int kind=value.get("kind").getAsInt();for(int i=0;i<value.get("filled").getAsInt();i++)owner.setItem(i,new ItemStack(kind==0?Items.IRON_INGOT:kind==1?Items.ENDER_PEARL:Items.IRON_PICKAXE,value.get("count").getAsInt()));need(owner.comparator()==value.get("signal").getAsInt(),"actual Source comparator profile "+value);}
  for(var entry:source.getAsJsonArray("operations")){var row=entry.getAsJsonObject();var owner=put(world,BASE,new CompoundTag());int kind=row.get("kind").getAsInt(),slot=row.get("slot").getAsInt();owner.setItem(slot,new ItemStack(kind==0?Items.IRON_INGOT:kind==1?Items.ENDER_PEARL:Items.IRON_PICKAXE,row.get("amount").getAsInt()));need(owner.getItem(slot).getCount()==row.get("installed").getAsInt(),"Source setter clamp");need(owner.removeItem(slot,row.get("take").getAsInt()).getCount()==row.get("extracted").getAsInt()&&owner.getItem(slot).getCount()==row.get("remaining").getAsInt(),"Source split");need(owner.comparator()==row.get("comparator").getAsInt(),"Source split comparator");need(owner.removeItemNoUpdate(slot).getCount()==row.get("removed").getAsInt()&&owner.isEmpty(),"Source remove all");}
  for(var row:source.getAsJsonArray("automation")){var value=row.getAsJsonObject();var owner=put(world,BASE,new CompoundTag());int initial=value.get("initial").getAsInt();if(initial>0)owner.setItem(0,new ItemStack(Items.IRON_INGOT,initial));var cap=world.getCapability(net.neoforged.neoforge.capabilities.Capabilities.ItemHandler.BLOCK,BASE,Direction.from3DDataValue(value.get("face").getAsInt()));need(cap!=null,"real registered capability every side");boolean simulate=value.get("simulate").getAsBoolean();need(cap.insertItem(0,new ItemStack(Items.IRON_INGOT,9),simulate).getCount()==value.get("remainder").getAsInt(),"Source automation insertion");need(owner.getItem(0).getCount()==value.get("afterInsert").getAsInt(),"Source automation inserted owner");need(cap.extractItem(0,5,simulate).getCount()==value.get("extracted").getAsInt()&&owner.getItem(0).getCount()==value.get("final").getAsInt(),"Source automation extraction");}
  for(var entry:source.getAsJsonArray("snapshots")){var row=entry.getAsJsonObject();var owner=put(world,BASE,new CompoundTag());int seed=row.get("seed").getAsInt();if(seed>0)owner.setItem(26,new ItemStack(Items.DIAMOND,seed==1?7:64));var raw=TagParser.parseTag(row.get("input").getAsString());owner.loadWithComponents(raw,world.registryAccess());if(owner.inert()){need(owner.isEmpty()&&owner.comparator()==0,"unsupported inventory inert");continue;}for(int i=0;i<27;i++)need(owner.getItem(i).getCount()==row.getAsJsonArray("slots").get(i).getAsJsonObject().get("count").getAsInt(),"actual Source repeated inventory read");}
 }
 private static void ownership(ServerLevel world)throws Exception{var owner=put(world,BASE,source("{Items:[{Slot:0b,id:\"minecraft:iron_ingot\",Count:4b},{Slot:26b,id:\"minecraft:diamond\",Count:7b}],PrivateField:\"opaque\"}"));need(!owner.inert()&&owner.getItem(26).getCount()==7,"actual Source inventory installed");observe=true;try{owner.loadWithComponents(owner.saveWithoutMetadata(world.registryAccess()),world.registryAccess());}finally{observe=false;}
  var picked=NativeStorageItemSettings.configuration(NativeStorageItemSettings.pick(ITEM,owner,world.registryAccess()));need(!picked.contains("Items")&&!picked.contains(NativeStorageInventory.SCHEMA)&&picked.getString("PrivateField").equals("opaque"),"configured appearance excludes inventory but preserves unowned private choices");var update=owner.getUpdateTag(world.registryAccess());need(!update.contains("Items")&&!update.contains("PrivateField")&&!update.contains("ForgeCaps"),"public projection inventory/opaque-free");var player=actor(world,BASE);need(owner.stillValid(player)&&owner.createMenu(7,player.getInventory(),player) instanceof net.minecraft.world.inventory.ChestMenu,"independent vanilla27 menu");var menu=owner.createMenu(8,player.getInventory(),player);menu.quickMoveStack(player,0);need(owner.getItem(0).isEmpty()&&player.getInventory().countItem(Items.IRON_INGOT)==4,"actual vanilla quickmove to player");player.getInventory().setItem(9,new ItemStack(Items.GOLD_INGOT,5));menu.quickMoveStack(player,27);need(owner.getItem(0).is(Items.GOLD_INGOT)&&owner.getItem(0).getCount()==5,"actual vanilla quickmove to Storage");
  long scans=owner.inventoryScans(),revision=owner.visual().revision();need(!owner.configure(player,NativeStorageSettings.fresh()),"unauthorized survival appearance edit refused");player.setGameMode(net.minecraft.world.level.GameType.CREATIVE);need(owner.configure(player,NativeStorageSettings.fresh())&&owner.inventoryScans()==scans,"appearance edits avoid inventory scans");var visual=owner.visual();owner.setItem(1,new ItemStack(Items.DIAMOND,1));need(owner.visual()==visual,"inventory mutation does not rebuild/send appearance");
  var bad=source("{Items:[{Slot:0b,id:\"minecraft:iron_ingot\",Count:4b},{Slot:26b,id:\"missing:owned\",Count:1b}],PrivateField:\"late-failure\"}");owner.loadWithComponents(bad,world.registryAccess());need(owner.inert()&&owner.isEmpty()&&owner.saveWithoutMetadata(world.registryAccess()).equals(bad),"late decode failure retains exact original with no prefix");need(!NativeStorageItemSettings.configuration(NativeStorageItemSettings.pick(ITEM,owner,world.registryAccess())).contains(NativeStorageEntity.RECOVERY),"creative inert pick cannot clone opaque inventory");var recovery=NativeStorageItemSettings.configuration(NativeStorageItemSettings.drop(ITEM,owner,world.registryAccess()));need(recovery.getCompound(NativeStorageEntity.RECOVERY).equals(bad),"mining recovery retains entire failed owner");boolean refused=false;try{NativeStorageItemSettings.prepare(TYPE,BASE,BLOCK.defaultBlockState(),recovery,world.registryAccess());}catch(IllegalArgumentException expected){refused=true;}need(refused,"recovery owner cannot be placed");
  owner=put(world,BASE.east(),new CompoundTag());owner.setItem(26,new ItemStack(Items.DIAMOND,7));var partial=source("{ForgeCaps:{\"foreign:owner\":{Marker:9}}}");owner.loadWithComponents(partial,world.registryAccess());var quarantined=owner.saveWithoutMetadata(world.registryAccess());need(owner.inert()&&owner.isEmpty()&&quarantined.getCompound("ForgeCaps").equals(partial.getCompound("ForgeCaps")),"partial unsupported load retains incoming opaque owner");need(NativeStorageInventory.read(quarantined.getCompound(NativeStorageEntity.PREVIOUS),world.registryAccess(),NativeStorageInventory.empty()).get(26).getCount()==7,"previous usable inventory quarantined in one recovery owner");owner.loadWithComponents(new CompoundTag(),world.registryAccess());need(owner.inert()&&owner.saveWithoutMetadata(world.registryAccess()).equals(quarantined),"appearance-only reload cannot erase quarantine");
  var adjacent=put(world,BASE.east(2),new CompoundTag());adjacent.setItem(0,new ItemStack(Items.DIAMOND,3));need(at(world,BASE.east()).isEmpty()&&adjacent.getItem(0).getCount()==3,"adjacent owners never merge");var handler=adjacent.itemHandler();adjacent.onChunkUnloaded();need(handler.extractItem(0,3,false).isEmpty()&&adjacent.getItem(0).getCount()==3,"stale capability cannot transfer unloaded ownership");adjacent.onLoad();need(handler.extractItem(0,1,false).getCount()==1,"deferred loaded owner resumes");
  for(int dx=0;dx<3;dx++)world.setChunkForced((BASE.getX()+dx)>>4,BASE.getZ()>>4,true);
 }
 private static void placement(ServerLevel world)throws Exception{for(int mode=0;mode<3;mode++){var pos=BASE.south(4+mode*2);world.getChunkAt(pos);world.setBlock(pos.below(),Blocks.STONE.defaultBlockState(),18);world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);var player=actor(world,pos.north());var stack=new ItemStack(ITEM,2);var tag=source("{Items:[{Slot:26b,id:\"minecraft:diamond\",Count:7b}],PrivateField:\"placed\"}");var root=new CompoundTag();root.put("BlockEntityTag",tag);stack.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(root));player.setItemInHand(InteractionHand.MAIN_HAND,stack);fault=mode;boolean threw=false;net.minecraft.world.InteractionResult result=net.minecraft.world.InteractionResult.FAIL;try{result=player.gameMode.useItemOn(player,world,stack,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atBottomCenterOf(pos),Direction.UP,pos.below(),false));}catch(IllegalArgumentException|IllegalStateException expected){threw=true;}finally{fault=0;}if(mode==0)need(!threw&&result.consumesAction()&&stack.getCount()==1&&at(world,pos).getItem(26).getCount()==7,"real GameMode configured survival placement one owner");else if(mode==1)need(threw&&stack.getCount()==2&&world.getBlockState(pos).isAir(),"failed install restores cell without consumption");else need(threw&&stack.getCount()==1&&at(world,pos).inert()&&at(world,pos).saveWithoutMetadata(world.registryAccess()).getList("Items",Tag.TAG_COMPOUND).size()==1,"failed rollback retains one inert consumed owner");}
  var pos=BASE.south(12);world.getChunkAt(pos);world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);world.setBlock(pos.below(),Blocks.STONE.defaultBlockState(),18);var player=actor(world,pos.north());var stack=new ItemStack(ITEM,2);var root=new CompoundTag();root.put("BlockEntityTag",source("{Items:[{Slot:0b,id:\"missing:owned\",Count:1b}]}"));stack.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(root));player.setItemInHand(InteractionHand.MAIN_HAND,stack);need(!player.gameMode.useItemOn(player,world,stack,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atBottomCenterOf(pos),Direction.UP,pos.below(),false)).consumesAction()&&stack.getCount()==2&&world.getBlockState(pos).isAir(),"unsupported ownership refused before world mutation/consumption");}
 private static void mining(ServerLevel world)throws Exception {for(boolean failed:new boolean[]{false,true})for(boolean creative:new boolean[]{false,true})for(boolean proper:new boolean[]{false,true}){var pos=BASE.west(6);var raw=failed?source("{Items:[{Slot:26b,id:\"missing:owned\",Count:1b}],OpaqueOwner:{Marker:37}}" ):source("{Items:[{Slot:26b,id:\"minecraft:iron_ingot\",Count:7b}],PrivateField:\"mined\"}");var owner=put(world,pos,raw);need(owner.inert()==failed,"mining fixture authority");var player=actor(world,pos);player.setGameMode(creative?net.minecraft.world.level.GameType.CREATIVE:net.minecraft.world.level.GameType.SURVIVAL);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(proper?Items.STONE_PICKAXE:Items.WOODEN_PICKAXE));need(world.getBlockState(pos).canHarvestBlock(world,pos,player)==proper,"actual private tool tags");capture=pos;DROPS.clear();try{need(player.gameMode.destroyBlock(pos)&&world.isEmptyBlock(pos),"actual GameMode mining");}finally{capture=null;}int blocks=0,iron=0;for(var stack:DROPS){if(stack.is(ITEM)){blocks+=stack.getCount();var choices=NativeStorageItemSettings.configuration(stack);if(failed)need(choices.getCompound(NativeStorageEntity.RECOVERY).equals(raw),"opaque mining recovery exact original");else need(!choices.contains("Items")&&choices.getString("PrivateField").equals("mined"),"configured mined block inventory-free");}else if(stack.is(Items.IRON_INGOT))iron+=stack.getCount();}need(blocks==(failed?1:!creative&&proper?1:0)&&iron==(failed?0:7),"one recovery owner or separately dropped contents, all4 modes failed="+failed+" creative="+creative+" proper="+proper+" blocks="+blocks+" iron="+iron);}
  var pos=BASE.west(6);var owner=put(world,pos,new CompoundTag());var tag=owner.saveWithoutMetadata(world.registryAccess());var rows=new ListTag();for(int i=0;i<8;i++){var row=new CompoundTag();row.putString("Label","Row "+i);row.putIntArray("RedstoneChannels",new int[]{i+1});row.putBoolean("Active",true);row.putLong("PulseUntil",900);rows.add(row);}var controls=new CompoundTag();controls.put("Rows",rows);controls.putString("Title","Storage choices");tag.put("RedstonePrimary",controls);owner.loadWithComponents(tag,world.registryAccess());var picked=NativeStorageItemSettings.configuration(NativeStorageItemSettings.pick(ITEM,owner,world.registryAccess()));var configured=picked.getCompound("RedstonePrimary").getList("Rows",Tag.TAG_COMPOUND);need(configured.size()==8&&!configured.getCompound(0).contains("Active")&&!configured.getCompound(0).contains("PulseUntil"),"Source8 standalone rows configured without active ownership");}
 private static void duplicateOwnership(ServerLevel world)throws Exception {
  JsonArray cases;try(var stream=new GZIPInputStream(Files.newInputStream(Path.of(System.getProperty("vandorlabs.storageDuplicateReference"))));var reader=new InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)){cases=JsonParser.parseReader(reader).getAsJsonArray();}need(cases.size()==8,"Source duplicate corpus coverage");
  for(int i=0;i<cases.size();i++){var row=cases.get(i).getAsJsonObject();var raw=source(row.get("input").getAsString());var owner=put(world,BASE.west(10),raw);if(row.get("ambiguous").getAsBoolean())need(owner.inert()&&owner.isEmpty()&&owner.saveWithoutMetadata(world.registryAccess()).equals(raw),"ambiguous duplicate credential/container retains complete original case="+i);else{var expected=com.vandorlabs.neoforge.inventory.NativeInventoryItems.legacy(source(row.get("final").getAsString()),world.registryAccess());need(!owner.inert()&&ItemStack.matches(owner.getItem(0),expected),"ordinary Source duplicate remains last-wins case="+i);if(row.has("nestedFinal")){var child=owner.getItem(0).get(net.minecraft.core.component.DataComponents.CONTAINER).getStackInSlot(0);var nested=com.vandorlabs.neoforge.inventory.NativeInventoryItems.legacy(source(row.get("nestedFinal").getAsString()),world.registryAccess());need(ItemStack.matches(child,nested),"ordinary nested duplicate remains Source last-wins");}}}
  var nativeDuplicate=source("{id:\"minecraft:chest\",count:1,components:{\"minecraft:container\":[{slot:0,item:{id:\"vandorlabs:data_chip\",count:1}},{slot:0,item:{id:\"minecraft:iron_ingot\",count:3}}]}}");boolean refused=false;try{com.vandorlabs.neoforge.inventory.NativeInventoryItems.modern(nativeDuplicate,world.registryAccess());}catch(IllegalArgumentException expected){refused=true;}need(refused,"native container duplicate cannot erase earlier credential");
 }
 private static void write(ServerLevel world)throws Exception{replay(world);ownership(world);placement(world);mining(world);duplicateOwnership(world);StorageEditorChecks.run(world,BASE.north(8));var cold=put(world,COLD,new CompoundTag());need(world.getChunkSource().getChunkNow((COLD.getX()-1)>>4,COLD.getZ()>>4)==null,"specific cold west begins absent");cold.onLoad();need(world.getChunkSource().getChunkNow((COLD.getX()-1)>>4,COLD.getZ()>>4)==null,"onLoad remains local-only");NativeStorageLifecycle.comparators(cold);need(world.getChunkSource().getChunkNow((COLD.getX()-1)>>4,COLD.getZ()>>4)==null,"comparator notifications do not force cold chunks");}
 private static void read(ServerLevel world){world.getChunkAt(BASE);var quarantined=at(world,BASE.east());need(quarantined!=null&&quarantined.inert(),"quarantined owner remains inert after complete-process restart");var saved=quarantined.saveWithoutMetadata(world.registryAccess());need(saved.getCompound("ForgeCaps").getCompound("foreign:owner").getInt("Marker")==9&&NativeStorageInventory.read(saved.getCompound(NativeStorageEntity.PREVIOUS),world.registryAccess(),NativeStorageInventory.empty()).get(26).getCount()==7,"opaque incoming and previous inventory survive restart exactly once");var normal=at(world,BASE.south(4));need(normal!=null&&!normal.inert()&&normal.getItem(26).getCount()==7,"native schema all27slots persists");var failed=at(world,BASE.south(8));need(failed!=null&&failed.inert()&&failed.saveWithoutMetadata(world.registryAccess()).getBoolean(NativeStorageEntity.PLACEMENT_RECOVERY),"placement recovery survives restart inert");}
 @SubscribeEvent public static void started(ServerStartedEvent event){if(!enabled())return;try{var world=event.getServer().overworld();if(phase().endsWith("write"))write(world);else read(world);event.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][storage-host] "+(phase().endsWith("write")?"write":"read")+" PASS checks="+checks);}catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][storage-host] FAIL "+failure);}finally{event.getServer().halt(false);}}
}
